package io.github.raincandyfx.rainium;

import io.github.raincandyfx.rainium.LyricEngine.Scheme;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;
import java.awt.geom.Rectangle2D;

import static io.github.raincandyfx.rainium.LyricKit.clamp;

/** Backgrounds behind a cut: patterns, skies, landscapes, tapes and light. Condensed re-creations; drawn only when the backdrop setting is above zero. */
final class LyricBg {
    private LyricBg() {}

    private static double h(long a, int b) { double x = Math.sin(a * 12.9898 + b * 78.233) * 43758.5453; return x - Math.floor(x); }

    private static Color c(Color x, double a) { return new Color(x.getRed(), x.getGreen(), x.getBlue(), (int) Math.round(255 * clamp(a))); }

    private static void ln(Graphics2D g, double x0, double y0, double x1, double y1) { g.draw(new Line2D.Double(x0, y0, x1, y1)); }

    /** Draws background key over a W x H picture; a is the overall strength (already scaled by the backdrop setting and fades). */
    static void paint(String key, Graphics2D g, Scheme sc, double t, double lt, long step, double a, int W, int H, long seed) {
        if (key == null || key.isEmpty() || key.equals("none") || a <= 0.01) return;
        Color A = sc.accent(), B = sc.accent2(), F = sc.fg(), D = sc.dim(), K = sc.bg();
        var old = g.getComposite();
        g.setStroke(new BasicStroke(1.4f));
        double u = clamp(lt / 3.0);
        switch (key) {
            case "auroraRibbons" -> { for (int r = 0; r < 4; r++) { Path2D p = new Path2D.Double(); double y0 = H * (0.25 + 0.12 * r); p.moveTo(0, y0); for (int x = 0; x <= W; x += 20) p.lineTo(x, y0 + Math.sin(x * 0.012 + t * 0.6 + r) * 28 + Math.sin(x * 0.03 + t) * 8); g.setStroke(new BasicStroke(26f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND)); g.setColor(c(r % 2 == 0 ? A : B, 0.18 * a)); g.draw(p); } }
            case "meshBlobs" -> { for (int i = 0; i < 5; i++) { double x = W * (0.5 + 0.4 * Math.sin(t * 0.3 + i * 1.7)), y = H * (0.5 + 0.4 * Math.cos(t * 0.27 + i * 2.3)), r = H * 0.5; g.setPaint(new RadialGradientPaint((float) x, (float) y, (float) r, new float[]{0f, 1f}, new Color[]{c(i % 2 == 0 ? A : B, 0.35 * a), c(K, 0)})); g.fill(new Rectangle2D.Double(0, 0, W, H)); } }
            case "duotoneSweep" -> { double x = (t * 60) % (W * 2) - W; g.setPaint(new GradientPaint((float) x, 0, c(A, 0.35 * a), (float) (x + W), H, c(B, 0.35 * a))); g.fill(new Rectangle2D.Double(0, 0, W, H)); }
            case "horizonGlow" -> { g.setPaint(new GradientPaint(0, H * 0.45f, c(K, 0), 0, H * 0.75f, c(A, 0.5 * a))); g.fill(new Rectangle2D.Double(0, 0, W, H)); g.setColor(c(F, 0.5 * a)); ln(g, 0, H * 0.72, W, H * 0.72); }
            case "seigaiha" -> { g.setColor(c(A, 0.22 * a)); double r = 36; for (int row = 0; row < H / (r * 0.5) + 2; row++) for (double x = (row % 2) * r; x < W + r * 2; x += r * 2) for (int k = 1; k <= 3; k++) g.draw(new Arc2D.Double(x - r * k / 3, row * r * 0.5 - r * k / 3, 2 * r * k / 3, 2 * r * k / 3, 0, 180, Arc2D.OPEN)); }
            case "asanoha" -> { g.setColor(c(A, 0.2 * a)); double s = 44; for (double y = 0; y < H + s; y += s) for (double x = 0; x < W + s; x += s) { ln(g, x, y, x + s / 2, y + s / 2); ln(g, x + s, y, x + s / 2, y + s / 2); ln(g, x + s / 2, y, x + s / 2, y + s); ln(g, x, y + s / 2, x + s, y + s / 2); } }
            case "houndstooth", "checker" -> { double s = key.equals("checker") ? 40 : 24; g.setColor(c(A, 0.18 * a)); for (int j = 0; j * s < H; j++) for (int i = 0; i * s < W; i++) if ((i + j) % 2 == 0) g.fill(new Rectangle2D.Double(i * s - (key.equals("checker") ? (t * 8) % (2 * s) : 0), j * s, s, s)); }
            case "herringbone" -> { g.setColor(c(A, 0.2 * a)); double s = 30; for (double y = 0; y < H + s; y += s / 2) for (double x = 0; x < W + s; x += s) { ln(g, x, y, x + s / 2, y + s / 2); ln(g, x + s / 2, y + s / 2, x + s, y); } }
            case "argyle" -> { double s = 56; for (int j = 0; j * s / 2 < H + s; j++) for (int i = 0; i * s < W + s; i++) { double x = i * s + (j % 2) * s / 2, y = j * s / 2; Path2D p = new Path2D.Double(); p.moveTo(x, y - s / 2); p.lineTo(x + s / 2, y); p.lineTo(x, y + s / 2); p.lineTo(x - s / 2, y); p.closePath(); g.setColor(c((i + j) % 2 == 0 ? A : B, 0.14 * a)); g.fill(p); } }
            case "tartan" -> { for (int i = 0; i < W; i += 36) { g.setColor(c(i % 72 == 0 ? A : B, 0.14 * a)); g.fill(new Rectangle2D.Double(i, 0, 14, H)); } for (int j = 0; j < H; j += 36) { g.setColor(c(j % 72 == 0 ? A : B, 0.14 * a)); g.fill(new Rectangle2D.Double(0, j, W, 14)); } }
            case "chevron" -> { g.setColor(c(A, 0.2 * a)); g.setStroke(new BasicStroke(10f)); for (double y = -40 + (t * 20) % 40; y < H + 40; y += 40) { Path2D p = new Path2D.Double(); p.moveTo(0, y + 30); p.lineTo(W / 2.0, y); p.lineTo(W, y + 30); g.draw(p); } }
            case "isoCubes" -> { double s = 40; for (int j = -1; j * s * 0.75 < H; j++) for (int i = -1; i * s * 1.1 < W; i++) { double x = i * s * 1.73 + (j & 1) * s * 0.86, y = j * s * 1.5; Path2D top = new Path2D.Double(); top.moveTo(x, y); top.lineTo(x + s * 0.86, y + s * 0.5); top.lineTo(x, y + s); top.lineTo(x - s * 0.86, y + s * 0.5); top.closePath(); g.setColor(c(A, 0.16 * a)); g.fill(top); g.setColor(c(B, 0.14 * a)); g.draw(top); } }
            case "hexGrid" -> { g.setColor(c(A, 0.22 * a)); double r = 30; for (int j = -1; j * r * 1.5 < H; j++) for (int i = -1; i * r * 1.73 < W; i++) { double x = i * r * 1.73 + (j & 1) * r * 0.866, y = j * r * 1.5; Path2D p = new Path2D.Double(); for (int k = 0; k < 6; k++) { double an = Math.PI / 6 + k * Math.PI / 3; if (k == 0) p.moveTo(x + r * Math.cos(an), y + r * Math.sin(an)); else p.lineTo(x + r * Math.cos(an), y + r * Math.sin(an)); } p.closePath(); g.draw(p); } }
            case "triTess" -> { double s = 50; for (int j = 0; j * s * 0.866 < H + s; j++) for (int i = -1; i * s < W + s; i++) { double x = i * s + (j & 1) * s / 2, y = j * s * 0.866; Path2D p = new Path2D.Double(); p.moveTo(x, y); p.lineTo(x + s, y); p.lineTo(x + s / 2, y + s * 0.866); p.closePath(); g.setColor(c(A, (0.06 + 0.1 * h(i * 31 + j, 3)) * a)); g.fill(p); } }
            case "moire" -> { g.setColor(c(A, 0.2 * a)); for (int k = 1; k < 30; k++) { double r = k * 20; g.draw(new Ellipse2D.Double(W * 0.4 - r, H / 2.0 - r, 2 * r, 2 * r)); g.draw(new Ellipse2D.Double(W * 0.6 + Math.sin(t * 0.4) * 30 - r, H / 2.0 - r, 2 * r, 2 * r)); } }
            case "squareTunnel", "concentric" -> { boolean sq = key.equals("squareTunnel"); g.setColor(c(A, 0.22 * a)); for (int k = 0; k < 14; k++) { double f = ((k + t * 0.6) % 14) / 14.0, w = W * f * 1.4, hh = H * f * 1.4; g.setStroke(new BasicStroke((float) (1 + f * 4))); if (sq) g.draw(new Rectangle2D.Double(W / 2.0 - w / 2, H / 2.0 - hh / 2, w, hh)); else g.draw(new Ellipse2D.Double(W / 2.0 - w / 2, H / 2.0 - w / 2, w, w)); } }
            case "spiralArms", "sunburst", "speedLines", "godRays" -> { int n = key.equals("godRays") ? 9 : 28; double rot = key.equals("sunburst") ? t * 0.1 : key.equals("spiralArms") ? t * 0.3 : 0; double cx = key.equals("godRays") ? W * 0.8 : W / 2.0, cy = key.equals("godRays") ? -20 : H / 2.0; for (int k = 0; k < n; k++) { double an = rot + k * Math.PI * 2 / n; Path2D p = new Path2D.Double(); double sp = key.equals("speedLines") ? 0.01 : 0.07; p.moveTo(cx, cy); p.lineTo(cx + Math.cos(an - sp) * 1200, cy + Math.sin(an - sp) * 1200); p.lineTo(cx + Math.cos(an + sp) * 1200, cy + Math.sin(an + sp) * 1200); p.closePath(); if (key.equals("speedLines") && k % 2 == 0) continue; g.setColor(c(key.equals("godRays") ? F : (k % 2 == 0 ? A : B), (key.equals("godRays") ? 0.1 : 0.14) * a)); g.fill(p); } }
            case "topoLines" -> { g.setColor(c(A, 0.22 * a)); for (int k = 0; k < 9; k++) { Path2D p = new Path2D.Double(); for (int x = 0; x <= W; x += 16) { double y = H * (0.1 + k * 0.1) + Math.sin(x * 0.02 + k + t * 0.2) * 22 + Math.sin(x * 0.05 + k * 2) * 8; if (x == 0) p.moveTo(x, y); else p.lineTo(x, y); } g.draw(p); } }
            case "ridgePlot" -> { for (int k = 0; k < 8; k++) { Path2D p = new Path2D.Double(); double y0 = H * (0.3 + k * 0.08); p.moveTo(0, H); for (int x = 0; x <= W; x += 10) p.lineTo(x, y0 - Math.max(0, Math.sin(x * 0.03 + k * 1.3 + t * 0.3)) * 26 * h(k, 1 + x / 160)); p.lineTo(W, H); p.closePath(); g.setColor(c(K, 0.8 * a)); g.fill(p); g.setColor(c(A, 0.5 * a)); g.draw(p); } }
            case "starfield", "twinkleSky", "bokehBg", "particlesBg" -> { boolean bk = key.equals("bokehBg"); int n = bk ? 16 : 70; for (int i = 0; i < n; i++) { double x = h(i, 1) * W, y = (bk ? h(i, 2) * H : (h(i, 2) * H + (key.equals("particlesBg") ? -t * (6 + h(i, 4) * 14) : 0))) ; y = ((y % H) + H) % H; double tw = 0.5 + 0.5 * Math.sin(t * (1 + h(i, 3) * 3) + i); double r = bk ? 10 + h(i, 5) * 26 : 0.8 + h(i, 5) * 1.8; g.setColor(c(i % 3 == 0 ? A : F, (bk ? 0.1 : 0.55 * tw) * a)); g.fill(new Ellipse2D.Double(x - r, y - r, 2 * r, 2 * r)); } }
            case "nightMoon" -> { g.setColor(c(F, 0.6 * a)); g.fill(new Ellipse2D.Double(W * 0.78, H * 0.14, 70, 70)); g.setColor(c(K, 0.95 * a)); g.fill(new Ellipse2D.Double(W * 0.78 + 18, H * 0.14 - 6, 66, 66)); for (int i = 0; i < 30; i++) { g.setColor(c(F, 0.4 * a * (0.5 + 0.5 * Math.sin(t * 2 + i)))); g.fill(new Rectangle2D.Double(h(i, 1) * W, h(i, 2) * H * 0.6, 1.6, 1.6)); } }
            case "skyline" -> { for (int i = 0; i < 16; i++) { double w = 30 + h(i, 1) * 30, x = i * W / 15.0 - 20, hh = 60 + h(i, 2) * 150; g.setColor(c(K, 0.9 * a)); g.fill(new Rectangle2D.Double(x, H - hh, w, hh)); g.setColor(c(A, 0.5 * a)); g.draw(new Rectangle2D.Double(x, H - hh, w, hh)); for (int k = 0; k < hh / 14; k++) if (h(i * 9 + k, 3) > 0.6) { g.setColor(c(F, 0.5 * a)); g.fill(new Rectangle2D.Double(x + 5 + h(k, 4) * (w - 12), H - hh + 6 + k * 14, 4, 4)); } } }
            case "sunsetSun" -> { g.setPaint(new GradientPaint(0, 0, c(B, 0.3 * a), 0, H * 0.7f, c(A, 0.35 * a))); g.fill(new Rectangle2D.Double(0, 0, W, H * 0.7)); g.setColor(c(F, 0.7 * a)); double sy = H * 0.5 + u * 20; g.fill(new Ellipse2D.Double(W / 2.0 - 70, sy - 70, 140, 140)); g.setColor(c(K, 0.9 * a)); g.fill(new Rectangle2D.Double(0, H * 0.7, W, H * 0.3)); }
            case "oceanWaves" -> { for (int k = 0; k < 6; k++) { Path2D p = new Path2D.Double(); double y0 = H * (0.55 + k * 0.08); p.moveTo(0, H); for (int x = 0; x <= W; x += 10) p.lineTo(x, y0 + Math.sin(x * 0.02 + t * (0.8 + k * 0.2) + k) * (6 + k * 2)); p.lineTo(W, H); p.closePath(); g.setColor(c(k % 2 == 0 ? A : B, 0.16 * a)); g.fill(p); } }
            case "rainWindow", "rainStreaks" -> { for (int i = 0; i < 40; i++) { double x = h(i, 1) * W, y = ((h(i, 2) * H + t * (60 + h(i, 3) * 120)) % (H + 40)) - 20; g.setColor(c(F, 0.25 * a)); ln(g, x, y, x - 3, y + 14); } }
            case "snowLayers" -> { for (int i = 0; i < 80; i++) { double d = 0.4 + h(i, 4), x = (h(i, 1) * W + Math.sin(t * 0.7 + i) * 12) % W, y = (h(i, 2) * H + t * 20 * d) % H; g.setColor(c(F, 0.45 * a * d)); g.fill(new Ellipse2D.Double(x, y, 2.2 * d, 2.2 * d)); } }
            case "fireworks" -> { for (int k = 0; k < 3; k++) { double ph = ((t * 0.5 + k * 0.33) % 1), cx = W * (0.2 + 0.3 * k), cy = H * (0.3 + 0.1 * (k % 2)); for (int i = 0; i < 18; i++) { double an = i * Math.PI * 2 / 18, r = ph * 70; g.setColor(c(i % 2 == 0 ? A : B, (1 - ph) * 0.8 * a)); g.fill(new Ellipse2D.Double(cx + Math.cos(an) * r - 1.5, cy + Math.sin(an) * r + ph * ph * 20 - 1.5, 3, 3)); } } }
            case "cloudLayers", "cloudPuffs" -> { for (int k = 0; k < 6; k++) { double x = ((k * 190 + t * (8 + k * 3)) % (W + 240)) - 120, y = H * (0.1 + 0.12 * (k % 4)); g.setColor(c(F, 0.12 * a)); for (int p = 0; p < 4; p++) g.fill(new Ellipse2D.Double(x + p * 28 - 14, y + (p % 2) * -8, 56, 34)); } }
            case "mountains" -> { for (int k = 0; k < 3; k++) { Path2D p = new Path2D.Double(); p.moveTo(0, H); for (int x = 0; x <= W; x += 20) p.lineTo(x, H * (0.5 + k * 0.1) - Math.abs(Math.sin(x * 0.011 + k * 2)) * 110 * (1 - k * 0.2)); p.lineTo(W, H); p.closePath(); g.setColor(c(k == 0 ? A : K, (0.2 + 0.25 * k) * a)); g.fill(p); } }
            case "filmStrip" -> { g.setColor(c(K, 0.8 * a)); g.fill(new Rectangle2D.Double(0, 0, W, 30)); g.fill(new Rectangle2D.Double(0, H - 30, W, 30)); g.setColor(c(F, 0.7 * a)); for (double x = -(t * 40) % 24; x < W; x += 24) { g.fill(new Rectangle2D.Double(x, 8, 12, 14)); g.fill(new Rectangle2D.Double(x, H - 22, 12, 14)); } }
            case "vhsBand", "tvBars" -> { if (key.equals("vhsBand")) { double y = (t * 90) % (H + 80) - 40; g.setColor(c(F, 0.14 * a)); g.fill(new Rectangle2D.Double(0, y, W, 24)); for (int i = 0; i < 6; i++) { g.setColor(c(A, 0.3 * a)); g.fill(new Rectangle2D.Double(h(step, i) * W * 0.6, y + i * 4, W * 0.3 * h(step, i + 9), 2)); } } else { Color[] cs = {Color.WHITE, Color.YELLOW, Color.CYAN, Color.GREEN, Color.MAGENTA, Color.RED, Color.BLUE}; for (int i = 0; i < 7; i++) { g.setColor(c(cs[i], 0.2 * a)); g.fill(new Rectangle2D.Double(i * W / 7.0, 0, W / 7.0 + 1, H * 0.6)); } } }
            case "tornPaper", "paperCut" -> { for (int k = 0; k < 3; k++) { Path2D p = new Path2D.Double(); double y0 = H * (0.3 + 0.2 * k); p.moveTo(0, H); p.lineTo(0, y0); for (int x = 0; x <= W; x += 16) p.lineTo(x, y0 + (h(x + k * 99, 2) - 0.5) * (key.equals("paperCut") ? 6 : 22) + (key.equals("paperCut") ? Math.sin(x * 0.012 + k * 2) * 28 : 0)); p.lineTo(W, H); p.closePath(); g.setColor(c(k % 2 == 0 ? A : B, 0.22 * a)); g.fill(p); } }
            case "vignettePulse", "spotlight" -> { double pulse = key.equals("spotlight") ? 0 : 0.5 + 0.5 * Math.sin(t * 2); float rad = (float) (H * (key.equals("spotlight") ? 0.55 : 0.8 - 0.05 * pulse)); g.setPaint(new RadialGradientPaint((float) (key.equals("spotlight") ? W / 2.0 + Math.sin(t * 0.6) * W * 0.2 : W / 2.0), H / 2f, rad, new float[]{0f, 1f}, new Color[]{c(K, 0), c(K, 0.8 * a)})); g.fill(new Rectangle2D.Double(0, 0, W, H)); }
            case "kaleidoscope" -> { for (int k = 0; k < 12; k++) { double an = k * Math.PI / 6 + t * 0.15; Path2D p = new Path2D.Double(); p.moveTo(W / 2.0, H / 2.0); p.lineTo(W / 2.0 + Math.cos(an) * 400, H / 2.0 + Math.sin(an) * 400); p.lineTo(W / 2.0 + Math.cos(an + 0.26) * 300, H / 2.0 + Math.sin(an + 0.26) * 300); p.closePath(); g.setColor(c(k % 2 == 0 ? A : B, 0.18 * a)); g.fill(p); } }
            case "marble", "noiseField" -> { for (int k = 0; k < 14; k++) { Path2D p = new Path2D.Double(); for (int x = 0; x <= W; x += 12) { double y = H * h(k, 1) + Math.sin(x * 0.01 * (1 + h(k, 2) * 2) + k + t * 0.1) * 40 + Math.sin(x * 0.04 + k) * 10; if (x == 0) p.moveTo(x, y); else p.lineTo(x, y); } g.setColor(c(k % 2 == 0 ? A : F, 0.14 * a)); g.draw(p); } }
            case "hrFailingLamp" -> { double fl = h(step / 2, 3) > 0.35 ? 1 : 0.15; g.setPaint(new RadialGradientPaint(W / 2f, 0, (float) (H * 0.9), new float[]{0f, 1f}, new Color[]{c(F, 0.35 * a * fl), c(K, 0)})); g.fill(new Rectangle2D.Double(0, 0, W, H)); g.setColor(c(F, 0.6 * a)); ln(g, W / 2.0, 0, W / 2.0, 20); }
            case "hrCorridor" -> { g.setColor(c(A, 0.2 * a)); for (int k = 0; k < 10; k++) { double f = (k + (t * 0.3) % 1) / 10.0, w = W * f, hh = H * f; g.draw(new Rectangle2D.Double(W / 2.0 - w / 2, H / 2.0 - hh / 2, w, hh)); } ln(g, 0, 0, W / 2.0 - 8, H / 2.0 - 5); ln(g, W, 0, W / 2.0 + 8, H / 2.0 - 5); ln(g, 0, H, W / 2.0 - 8, H / 2.0 + 5); ln(g, W, H, W / 2.0 + 8, H / 2.0 + 5); }
            case "hrMold" -> { for (int i = 0; i < 24; i++) { double x = h(i, 1) * W, y = h(i, 2) * H, r = 12 + h(i, 3) * 30; g.setPaint(new RadialGradientPaint((float) x, (float) y, (float) r, new float[]{0f, 1f}, new Color[]{c(A, 0.22 * a), c(A, 0)})); g.fill(new Ellipse2D.Double(x - r, y - r, 2 * r, 2 * r)); } }
            case "hrDeadTrees" -> { g.setColor(c(K, 0.9 * a)); g.setStroke(new BasicStroke(3f)); for (int i = 0; i < 7; i++) { double x = i * W / 6.0, y = H; double hh = 80 + h(i, 1) * 120; ln(g, x, y, x + (h(i, 2) - 0.5) * 20, y - hh); for (int b = 1; b < 5; b++) ln(g, x, y - hh * b / 5, x + (b % 2 == 0 ? 1 : -1) * (14 + h(i, b) * 24), y - hh * b / 5 - 18); } }
            case "halftoneFade" -> { g.setColor(c(A, 0.3 * a)); double d = 16; for (double y = 0; y < H; y += d) for (double x = (int) (y / d) % 2 * d / 2; x < W; x += d) { double r = d * 0.5 * (x / W); g.fill(new Ellipse2D.Double(x - r / 2, y - r / 2, r, r)); } }
            case "bigStripes" -> { for (int i = 0; i < 8; i++) if (i % 2 == 0) { g.setColor(c(A, 0.14 * a)); g.fill(new Rectangle2D.Double(i * W / 8.0, 0, W / 8.0, H)); } }
            case "splitV" -> { g.setColor(c(A, 0.2 * a)); g.fill(new Rectangle2D.Double(0, 0, W / 2.0, H)); g.setColor(c(B, 0.2 * a)); g.fill(new Rectangle2D.Double(W / 2.0, 0, W / 2.0, H)); }
            case "splitH" -> { g.setColor(c(A, 0.2 * a)); g.fill(new Rectangle2D.Double(0, 0, W, H / 2.0)); g.setColor(c(B, 0.2 * a)); g.fill(new Rectangle2D.Double(0, H / 2.0, W, H / 2.0)); }
            case "splitDiag" -> { Path2D p = new Path2D.Double(); p.moveTo(0, 0); p.lineTo(W, 0); p.lineTo(0, H); p.closePath(); g.setColor(c(A, 0.22 * a)); g.fill(p); g.setColor(c(B, 0.18 * a)); Path2D q = new Path2D.Double(); q.moveTo(W, 0); q.lineTo(W, H); q.lineTo(0, H); q.closePath(); g.fill(q); }
            case "gradientSweep" -> { double x = (t * 80) % (W * 2) - W / 2.0; g.setPaint(new GradientPaint((float) x, 0, c(A, 0.3 * a), (float) (x + W), 0, c(B, 0.3 * a))); g.fill(new Rectangle2D.Double(0, 0, W, H)); }
            case "bigChar" -> { g.setColor(c(A, 0.16 * a)); g.setFont(new java.awt.Font(java.awt.Font.SANS_SERIF, java.awt.Font.BOLD, 420)); String ch = String.valueOf((char) ('A' + (int) (h(seed, 1) * 26))); g.drawString(ch, (float) (W * 0.25 + Math.sin(t * 0.4) * 10), (float) (H * 0.95)); }
            case "scanBars" -> { g.setColor(c(F, 0.1 * a)); for (double y = 0; y < H; y += 6) g.fill(new Rectangle2D.Double(0, y, W, 2)); double y = (t * 60) % H; g.setColor(c(A, 0.18 * a)); g.fill(new Rectangle2D.Double(0, y, W, 14)); }
            case "dotGrid", "polka" -> { double s = key.equals("polka") ? 38 : 22; g.setColor(c(A, 0.28 * a)); for (double y = s / 2; y < H; y += s) for (double x = s / 2 + (key.equals("polka") && ((int) (y / s) & 1) == 1 ? s / 2 : 0); x < W; x += s) { double r = key.equals("polka") ? 5 : 1.6; g.fill(new Ellipse2D.Double(x - r, y - r, 2 * r, 2 * r)); } }
            case "retroGrid" -> { g.setColor(c(A, 0.35 * a)); double hz = H * 0.5; ln(g, 0, hz, W, hz); for (int i = -10; i <= 10; i++) ln(g, W / 2.0, hz, W / 2.0 + i * 120, H); for (int k = 1; k <= 8; k++) { double f = Math.pow(((k + (t * 0.5) % 1) / 8.0), 2); ln(g, 0, hz + (H - hz) * f, W, hz + (H - hz) * f); } }
            case "ripples", "rainRipples" -> { for (int k = 0; k < 4; k++) { double ph = (t * 0.4 + k * 0.25) % 1, x = W * (0.2 + 0.2 * k + 0.05 * h(k, 1)), y = H * (0.3 + 0.4 * h(k, 2)); g.setColor(c(A, (1 - ph) * 0.4 * a)); double r = ph * 90; g.draw(new Ellipse2D.Double(x - r, y - r * 0.4, 2 * r, 0.8 * r)); } }
            case "eqBars" -> { int n = 40; for (int i = 0; i < n; i++) { double v = 0.3 + 0.7 * Math.abs(Math.sin(t * 3 + i * 0.7) * Math.sin(t * 1.7 + i)); g.setColor(c(i % 2 == 0 ? A : B, 0.25 * a)); g.fill(new Rectangle2D.Double(i * W / (double) n + 2, H - v * H * 0.35, W / (double) n - 4, v * H * 0.35)); } }
            case "borderFrame" -> { g.setColor(c(A, 0.7 * a)); g.setStroke(new BasicStroke(3f)); g.draw(new Rectangle2D.Double(10, 10, W - 20, H - 20)); g.setStroke(new BasicStroke(1f)); g.draw(new Rectangle2D.Double(16, 16, W - 32, H - 32)); }
            case "letterbox" -> { g.setColor(c(Color.BLACK, 0.85 * a)); g.fill(new Rectangle2D.Double(0, 0, W, H * 0.12)); g.fill(new Rectangle2D.Double(0, H * 0.88, W, H * 0.12)); }
            default -> { }
        }
        g.setComposite(old);
    }
}
